-- ─────────────────────────────────────────────────────────────────────────────
-- Hand-written constraints (not expressible in the Prisma schema)
-- ─────────────────────────────────────────────────────────────────────────────

-- users
ALTER TABLE "users"
  ADD CONSTRAINT "users_username_format" CHECK ("username" ~ '^[A-Za-z0-9_.]{3,30}$'),
  ADD CONSTRAINT "users_phone_e164" CHECK ("phone" IS NULL OR "phone" ~ '^\+[1-9][0-9]{6,14}$'),
  ADD CONSTRAINT "users_birth_date_past" CHECK ("birth_date" IS NULL OR "birth_date" <= CURRENT_DATE);

-- user_preferences
ALTER TABLE "user_preferences"
  ADD CONSTRAINT "user_preferences_budget_non_negative" CHECK (
    ("budget_min_paise" IS NULL OR "budget_min_paise" >= 0) AND
    ("budget_max_paise" IS NULL OR "budget_max_paise" >= 0)),
  ADD CONSTRAINT "user_preferences_budget_range" CHECK (
    "budget_min_paise" IS NULL OR "budget_max_paise" IS NULL OR "budget_min_paise" <= "budget_max_paise");

-- user_blocks, follows: no self-relations
ALTER TABLE "user_blocks" ADD CONSTRAINT "user_blocks_not_self" CHECK ("blocker_id" <> "blocked_id");
ALTER TABLE "follows" ADD CONSTRAINT "follows_not_self" CHECK ("follower_id" <> "followee_id");

-- motorcycles
ALTER TABLE "motorcycles"
  ADD CONSTRAINT "motorcycles_year_range" CHECK ("year" IS NULL OR "year" BETWEEN 1900 AND 2100),
  ADD CONSTRAINT "motorcycles_engine_cc_range" CHECK ("engine_cc" IS NULL OR "engine_cc" BETWEEN 50 AND 3000);
-- At most one primary motorcycle per owner.
CREATE UNIQUE INDEX "motorcycles_one_primary_per_owner" ON "motorcycles" ("owner_id") WHERE "is_primary";

-- trips
ALTER TABLE "trips"
  ADD CONSTRAINT "trips_participant_limits" CHECK (
    "min_participants" >= 1 AND "max_participants" BETWEEN 2 AND 500 AND "min_participants" <= "max_participants"),
  ADD CONSTRAINT "trips_return_after_departure" CHECK ("return_at" IS NULL OR "return_at" >= "departure_at"),
  ADD CONSTRAINT "trips_budget_non_negative" CHECK ("estimated_budget_paise" IS NULL OR "estimated_budget_paise" >= 0),
  ADD CONSTRAINT "trips_distance_non_negative" CHECK ("estimated_distance_km" IS NULL OR "estimated_distance_km" >= 0),
  ADD CONSTRAINT "trips_currency_format" CHECK ("currency" ~ '^[A-Z]{3}$'),
  -- Ride mode is always a motorcycle ride, and motorcycle rides are always Ride mode.
  ADD CONSTRAINT "trips_mode_matches_activity" CHECK (("mode" = 'RIDE') = ("activity_type" = 'MOTORCYCLE_RIDE')),
  -- A trip is commercial if and only if it is a departure of a commercial package.
  -- Community trips can never carry a package (and so can never be sold).
  ADD CONSTRAINT "trips_commercial_requires_package" CHECK (
    ("trip_type" = 'COMMERCIAL_PAID') = ("commercial_package_id" IS NOT NULL)),
  -- Community trips are cost-sharing only: the budget is an estimate, never a fare.
  ADD CONSTRAINT "trips_commercial_has_no_budget_estimate" CHECK (
    "trip_type" = 'COMMUNITY_FREE' OR "estimated_budget_paise" IS NULL),
  -- Only drafts may lack a mapped origin and destination.
  ADD CONSTRAINT "trips_published_has_locations" CHECK (
    "status" = 'DRAFT' OR ("origin" IS NOT NULL AND "destination" IS NOT NULL));

-- trip_stops
ALTER TABLE "trip_stops" ADD CONSTRAINT "trip_stops_position_positive" CHECK ("position" >= 1);

-- trip_participants: exactly one organiser per trip.
CREATE UNIQUE INDEX "trip_participants_one_organiser" ON "trip_participants" ("trip_id") WHERE "role" = 'ORGANISER';

-- conversations: each type links to exactly the right parent.
ALTER TABLE "conversations" ADD CONSTRAINT "conversations_parent_matches_type" CHECK (
  ("type" = 'TRIP_GROUP' AND "trip_id" IS NOT NULL AND "community_id" IS NULL AND "direct_key" IS NULL) OR
  ("type" = 'COMMUNITY' AND "community_id" IS NOT NULL AND "trip_id" IS NULL AND "direct_key" IS NULL) OR
  ("type" = 'DIRECT' AND "direct_key" IS NOT NULL AND "trip_id" IS NULL AND "community_id" IS NULL));

-- messages
ALTER TABLE "messages" ADD CONSTRAINT "messages_content_present" CHECK (
  ("type" = 'TEXT' AND "body" IS NOT NULL) OR
  ("type" = 'IMAGE' AND "attachment_key" IS NOT NULL) OR
  ("type" = 'SYSTEM' AND "body" IS NOT NULL AND "sender_id" IS NULL) OR
  "deleted_at" IS NOT NULL);

-- reviews
ALTER TABLE "reviews"
  ADD CONSTRAINT "reviews_rating_range" CHECK ("rating" BETWEEN 1 AND 5),
  ADD CONSTRAINT "reviews_not_self" CHECK ("reviewer_id" <> "reviewee_id");

-- location_sessions: live location is time-limited (at most 24 hours).
ALTER TABLE "location_sessions" ADD CONSTRAINT "location_sessions_time_limited" CHECK (
  "expires_at" > "started_at" AND "expires_at" <= "started_at" + INTERVAL '24 hours');
-- At most one active session per user per trip.
CREATE UNIQUE INDEX "location_sessions_one_active" ON "location_sessions" ("trip_id", "user_id") WHERE "status" = 'ACTIVE';

-- commercial_operators
ALTER TABLE "commercial_operators" ADD CONSTRAINT "commercial_operators_verified_has_timestamp" CHECK (
  "verification_status" <> 'VERIFIED' OR "verified_at" IS NOT NULL);

-- commercial_packages
ALTER TABLE "commercial_packages"
  ADD CONSTRAINT "commercial_packages_price_positive" CHECK ("price_paise" > 0),
  ADD CONSTRAINT "commercial_packages_duration_positive" CHECK ("duration_days" >= 1),
  ADD CONSTRAINT "commercial_packages_group_size_positive" CHECK ("max_group_size" >= 1),
  ADD CONSTRAINT "commercial_packages_currency_format" CHECK ("currency" ~ '^[A-Z]{3}$'),
  ADD CONSTRAINT "commercial_packages_mode_matches_activity" CHECK (("mode" = 'RIDE') = ("activity_type" = 'MOTORCYCLE_RIDE'));

-- bookings
ALTER TABLE "bookings"
  ADD CONSTRAINT "bookings_seats_positive" CHECK ("seats" >= 1),
  ADD CONSTRAINT "bookings_amounts_non_negative" CHECK (
    "unit_price_paise" >= 0 AND "platform_fee_paise" >= 0 AND "total_amount_paise" >= 0),
  ADD CONSTRAINT "bookings_total_matches" CHECK (
    "total_amount_paise" = "unit_price_paise" * "seats" + "platform_fee_paise"),
  ADD CONSTRAINT "bookings_currency_format" CHECK ("currency" ~ '^[A-Z]{3}$');

-- payments
ALTER TABLE "payments"
  ADD CONSTRAINT "payments_exactly_one_purpose" CHECK (
    ("booking_id" IS NOT NULL)::int + ("subscription_id" IS NOT NULL)::int = 1),
  ADD CONSTRAINT "payments_amount_positive" CHECK ("amount_paise" > 0),
  ADD CONSTRAINT "payments_refund_within_amount" CHECK (
    "refunded_amount_paise" >= 0 AND "refunded_amount_paise" <= "amount_paise"),
  ADD CONSTRAINT "payments_currency_format" CHECK ("currency" ~ '^[A-Z]{3}$');

-- subscription_plans / subscriptions
ALTER TABLE "subscription_plans"
  ADD CONSTRAINT "subscription_plans_price_non_negative" CHECK ("price_paise" >= 0),
  ADD CONSTRAINT "subscription_plans_currency_format" CHECK ("currency" ~ '^[A-Z]{3}$');
ALTER TABLE "subscriptions" ADD CONSTRAINT "subscriptions_period_order" CHECK (
  "current_period_end" > "current_period_start");
-- At most one live subscription per user.
CREATE UNIQUE INDEX "subscriptions_one_live_per_user" ON "subscriptions" ("user_id")
  WHERE "status" IN ('TRIALING', 'ACTIVE', 'PAST_DUE');

-- ─────────────────────────────────────────────────────────────────────────────
-- Triggers
-- ─────────────────────────────────────────────────────────────────────────────

-- Bookings may only point at COMMERCIAL_PAID trips of the same package, so a free
-- community trip can never be sold (no paid passenger transport through community trips).
CREATE FUNCTION "bookings_enforce_commercial_trip"() RETURNS trigger AS $$
DECLARE
  trip_kind "TripType";
  trip_package uuid;
BEGIN
  IF NEW."trip_id" IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT "trip_type", "commercial_package_id" INTO trip_kind, trip_package
    FROM "trips" WHERE "id" = NEW."trip_id";
  IF trip_kind IS DISTINCT FROM 'COMMERCIAL_PAID' THEN
    RAISE EXCEPTION 'Bookings can only reference COMMERCIAL_PAID trips'
      USING ERRCODE = 'check_violation', CONSTRAINT = 'bookings_commercial_trip_only';
  END IF;
  IF trip_package IS DISTINCT FROM NEW."package_id" THEN
    RAISE EXCEPTION 'Booking package does not match the trip''s package'
      USING ERRCODE = 'check_violation', CONSTRAINT = 'bookings_trip_package_match';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "bookings_enforce_commercial_trip"
  BEFORE INSERT OR UPDATE OF "trip_id", "package_id" ON "bookings"
  FOR EACH ROW EXECUTE FUNCTION "bookings_enforce_commercial_trip"();

-- Commercial trips may only be created from packages whose operator is VERIFIED.
CREATE FUNCTION "trips_enforce_verified_operator"() RETURNS trigger AS $$
DECLARE
  operator_status "OperatorVerificationStatus";
BEGIN
  IF NEW."trip_type" <> 'COMMERCIAL_PAID' THEN
    RETURN NEW;
  END IF;
  SELECT o."verification_status" INTO operator_status
    FROM "commercial_packages" p JOIN "commercial_operators" o ON o."id" = p."operator_id"
    WHERE p."id" = NEW."commercial_package_id";
  IF operator_status IS DISTINCT FROM 'VERIFIED' THEN
    RAISE EXCEPTION 'Commercial trips require a VERIFIED operator'
      USING ERRCODE = 'check_violation', CONSTRAINT = 'trips_commercial_verified_operator';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "trips_enforce_verified_operator"
  BEFORE INSERT OR UPDATE OF "trip_type", "commercial_package_id" ON "trips"
  FOR EACH ROW EXECUTE FUNCTION "trips_enforce_verified_operator"();

-- Packages can only be PUBLISHED by VERIFIED operators.
CREATE FUNCTION "commercial_packages_enforce_verified_operator"() RETURNS trigger AS $$
DECLARE
  operator_status "OperatorVerificationStatus";
BEGIN
  IF NEW."status" <> 'PUBLISHED' THEN
    RETURN NEW;
  END IF;
  SELECT "verification_status" INTO operator_status
    FROM "commercial_operators" WHERE "id" = NEW."operator_id";
  IF operator_status IS DISTINCT FROM 'VERIFIED' THEN
    RAISE EXCEPTION 'Only VERIFIED operators can publish packages'
      USING ERRCODE = 'check_violation', CONSTRAINT = 'commercial_packages_verified_operator';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "commercial_packages_enforce_verified_operator"
  BEFORE INSERT OR UPDATE OF "status", "operator_id" ON "commercial_packages"
  FOR EACH ROW EXECUTE FUNCTION "commercial_packages_enforce_verified_operator"();

-- audit_logs are append-only. The only permitted update is the FK clearing actor_id
-- when a user row is erased (ON DELETE SET NULL); everything else is rejected.
CREATE FUNCTION "audit_logs_append_only"() RETURNS trigger AS $$
BEGIN
  IF TG_OP = 'UPDATE'
     AND NEW."actor_id" IS NULL AND OLD."actor_id" IS NOT NULL
     AND (to_jsonb(NEW) - 'actor_id') = (to_jsonb(OLD) - 'actor_id') THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'audit_logs is append-only (% not allowed)', TG_OP
    USING ERRCODE = 'insufficient_privilege';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "audit_logs_append_only"
  BEFORE UPDATE OR DELETE ON "audit_logs"
  FOR EACH ROW EXECUTE FUNCTION "audit_logs_append_only"();
